import{_ as r,o,c as n,ag as s}from"./chunks/framework.KxDd3USm.js";const q=JSON.parse('{"title":"03.8 CMM 与 CMMI ★","description":"","frontmatter":{},"headers":[],"relativePath":"03-软件工程基础/08-CMM与CMMI.md","filePath":"03-软件工程基础/08-CMM与CMMI.md"}'),d={name:"03-软件工程基础/08-CMM与CMMI.md"};function g(a,t,e,M,C,u){return o(),n("div",null,[...t[0]||(t[0]=[s('<h1 id="_03-8-cmm-与-cmmi-★" tabindex="-1">03.8 CMM 与 CMMI ★ <a class="header-anchor" href="#_03-8-cmm-与-cmmi-★" aria-label="Permalink to &quot;03.8 CMM 与 CMMI ★&quot;">​</a></h1><h3 id="_8-1-cmm-五级-背顺序-抓关键词" tabindex="-1">8.1 CMM 五级（背顺序 + 抓关键词） <a class="header-anchor" href="#_8-1-cmm-五级-背顺序-抓关键词" aria-label="Permalink to &quot;8.1 CMM 五级（背顺序 + 抓关键词）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>级别</th><th>名称</th><th>关键词识别</th></tr></thead><tbody><tr><td>1</td><td><strong>初始级</strong></td><td>杂乱无章、甚至混乱；几乎没有明确定义的步骤；项目成功<strong>完全依赖个人努力和英雄式核心人物</strong></td></tr><tr><td>2</td><td><strong>可重复级</strong></td><td>建立了<strong>基本的项目管理过程与实践</strong>，用来跟踪<strong>项目费用、进度和功能特性</strong>；有必要的过程准则来<strong>重复</strong>以前在同类项目中的成功</td></tr><tr><td>3</td><td><strong>已定义级</strong></td><td>管理和工程两方面的过程已经<strong>文档化、标准化</strong>，并综合成整个开发组织的<strong>标准过程</strong></td></tr><tr><td>4</td><td><strong>已管理级</strong>（已定量管理级）</td><td>制定了软件过程和产品质量的<strong>详细度量标准</strong>（<strong>定量</strong>）</td></tr><tr><td>5</td><td><strong>优化级</strong></td><td>加强<strong>定量分析</strong>，通过过程质量反馈与新观念、新技术的反馈，使过程能<strong>不断持续改进</strong></td></tr></tbody></table><p><strong>口诀</strong>：<strong>初、重、定、管、优</strong>（初始—可重复—已定义—已管理—优化）。</p><p><strong>考法就是配对</strong>：抓&quot;文档化标准化&quot;→ 3 级；&quot;<strong>定量/量化</strong>&quot;→ 4 级；&quot;<strong>持续改进</strong>&quot;→ 5 级；&quot;<strong>重复</strong>以往成功&quot;→ 2 级；&quot;靠个人英雄&quot;→ 1 级。<strong>3/4/5 三级的区分全在三个词上：标准化、定量、持续改进。</strong></p><p><strong>同一团队的升级故事</strong>：甲团队项目成败靠资深工程师临场救火，是 1 级；后来能复用上次的计划、跟踪成本与进度，是 2 级；再后来所有项目都按组织发布的需求、设计、测试流程执行，是 3 级；若团队开始用缺陷密度、交付周期等数据控制过程，才到 4 级；用这些数据找出瓶颈、试验改进措施并持续优化，才是 5 级。</p><p><strong>反例</strong>：“已经有统一流程，所以进入 5 级”错。统一流程只说明<strong>标准化</strong>，对应 3 级；没有量化控制不能到 4 级，有量化但未以反馈持续改进也不能到 5 级。</p><h3 id="_8-2-cmmi-的两种表示法-一阶段式-连续式" tabindex="-1">8.2 CMMI 的两种表示法（一阶段式 / 连续式） <a class="header-anchor" href="#_8-2-cmmi-的两种表示法-一阶段式-连续式" aria-label="Permalink to &quot;8.2 CMMI 的两种表示法（一阶段式 / 连续式）&quot;">​</a></h3><p><strong>CMMI（能力成熟度模型集成）</strong> 把 CMM 扩成了集成模型，有<strong>两种表示法</strong>：</p><p><strong>① 阶段式（阶段式模型）</strong>——按&quot;组织整体&quot;分五级，与 CMM 五级一一对应：</p><table tabindex="0"><thead><tr><th>级别</th><th>名称</th></tr></thead><tbody><tr><td>1</td><td>初始级</td></tr><tr><td>2</td><td><strong>已管理级</strong>（CMM 的&quot;可重复级&quot;在这里叫已管理级）</td></tr><tr><td>3</td><td>已定义级</td></tr><tr><td>4</td><td><strong>定量管理级</strong></td></tr><tr><td>5</td><td>优化级</td></tr></tbody></table><p><strong>② 连续式（连续式模型）</strong>——按&quot;单个过程域的能力&quot;分六级 <strong>CL0–CL5</strong>：</p><table tabindex="0"><thead><tr><th>等级</th><th>名称</th><th>一句话</th></tr></thead><tbody><tr><td>CL0</td><td>未完成的</td><td>过程域未执行，或未达到 CL1 的全部目标</td></tr><tr><td>CL1</td><td><strong>已执行的</strong></td><td>过程能把<strong>可标识的输入工作产品转换成可标识的输出工作产品</strong></td></tr><tr><td>CL2</td><td><strong>已管理的</strong></td><td>重点是把已管理的过程<strong>制度化</strong></td></tr><tr><td>CL3</td><td><strong>已定义级的</strong></td><td>重点是把已定义的过程<strong>制度化</strong></td></tr><tr><td>CL4</td><td><strong>定量管理的</strong></td><td>重点是<strong>可定量管理</strong>的过程制度化</td></tr><tr><td>CL5</td><td><strong>优化的</strong></td><td>用<strong>量化（统计学）手段改变和优化</strong>过程域，满足客户改变与持续改进的需求</td></tr></tbody></table><p><strong>阶段式 vs 连续式别混</strong>：<strong>阶段式看&quot;组织整体到了第几级&quot;（5 级）</strong>；<strong>连续式看&quot;某一个过程域自身的能力等级&quot;（CL0–CL5，6 级）</strong>。题干说&quot;<strong>某个过程域</strong>……&quot;→ 连续式；说&quot;<strong>整个组织</strong>……&quot;→ 阶段式。</p><p><strong>最小判别例</strong>：某公司整体尚未取得 3 级评估，但“配置管理”过程已能按计划执行、被度量和控制，题干问的是一个过程域的能力，应看<strong>连续式 CL2</strong>，不能回答“公司整体 2 级”。反过来，题干若说“组织的软件过程已标准化”，才按阶段式或 CMM 的组织等级判断。</p><h3 id="_8-3-应试动作" tabindex="-1">8.3 应试动作 <a class="header-anchor" href="#_8-3-应试动作" aria-label="Permalink to &quot;8.3 应试动作&quot;">​</a></h3><p>背两串顺序：<strong>CMM/CMMI 阶段式五级 = 初、重定管优</strong>（CMMI 里&quot;可重复&quot;叫&quot;已管理&quot;）；<strong>连续式 = CL0 未完成 → CL1 已执行 → CL2 已管理 → CL3 已定义 → CL4 定量管理 → CL5 优化</strong>。做题先抓三个关键词（标准化=3、定量=4、持续改进=5），再判断问的是&quot;整个组织&quot;还是&quot;某个过程域&quot;。</p>',17)])])}const i=r(d,[["render",g]]);export{q as __pageData,i as default};
